using System.IO; namespace CubeAntivirus.Modules; public sealed class HoneyPotManager : IDisposable { private readonly FileSystemWatcher _watcher; public string Root { get; } public event EventHandler<string>? ActivityDetected; public HoneyPotManager() { Root = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "CubeAntivirus", "HoneyPot"); Directory.CreateDirectory(Root); Create("passwords.txt", "DECOY FILE - no real credentials."); Create("crypto_keys.dat", "DECOY DATA - synthetic test content."); _watcher = new FileSystemWatcher(Root) { IncludeSubdirectories = true, NotifyFilter = NotifyFilters.FileName | NotifyFilters.LastWrite | NotifyFilters.Size, EnableRaisingEvents = true }; _watcher.Changed += Changed; _watcher.Created += Changed; _watcher.Deleted += Changed; _watcher.Renamed += Renamed; } private void Create(string name, string content) { var p = Path.Combine(Root, name); if (!File.Exists(p)) File.WriteAllText(p, content); } private void Changed(object s, FileSystemEventArgs e) => ActivityDetected?.Invoke(this, $"{e.ChangeType}: {e.FullPath}"); private void Renamed(object s, RenamedEventArgs e) => ActivityDetected?.Invoke(this, $"Renamed: {e.OldFullPath} -> {e.FullPath}"); public void Dispose() => _watcher.Dispose(); }